using System.Windows; namespace WpfSemana02; public partial class ConductoresWindow:Window { public ConductoresWindow(){InitializeComponent();Actualizar();} void Actualizar(){dgConductores.ItemsSource=null;dgConductores.ItemsSource=Datos.Conductores;} private void Guardar_Click(object s,RoutedEventArgs e){var n=txtNombre.Text.Trim();var l=txtLicencia.Text.Trim().ToUpper();if(n.Length<3||l.Length<5){MessageBox.Show("Ingrese un nombre y una licencia válidos.");return;}if(Datos.Conductores.Any(x=>x.Licencia.Equals(l,StringComparison.OrdinalIgnoreCase))){MessageBox.Show("La licencia ya está registrada.");return;}Datos.Conductores.Add(new(){Id=Datos.SiguienteId(Datos.Conductores,x=>x.Id),Nombre=n,Licencia=l,Transporte=txtTransporte.Text.Trim()});Datos.Guardar();txtNombre.Clear();txtLicencia.Clear();txtTransporte.Clear();Actualizar();}private void Eliminar_Click(object s,System.Windows.Input.MouseButtonEventArgs e){if(dgConductores.SelectedItem is Conductor c&&MessageBox.Show("¿Eliminar conductor?","Confirmar",MessageBoxButton.YesNo)==MessageBoxResult.Yes){if(Datos.Ingresos.Any(x=>x.Conductor==c.Nombre)){MessageBox.Show("No se puede eliminar porque tiene movimientos asociados.");return;}Datos.Conductores.Remove(c);Datos.Guardar();Actualizar();}}}
